sources.theme/maps/yazi.toml:
[app]
overall = { bg = "canvas_bg" }

[mgr]
cwd            = { fg = "info_text_on_canvas" }
find_keyword   = { fg = "on_warning_fill_on_canvas", bg = "warning_fill_on_canvas", italic = true }
find_position  = { fg = "warning_text_on_canvas", bg = "reset", italic = true }
symlink_target = { fg = "muted_on_canvas", italic = true }

# Equal foreground and background intentionally render a solid marker cell.
marker_copied   = { fg = "success_fill_on_canvas", bg = "success_fill_on_canvas" }
marker_cut      = { fg = "error_fill_on_canvas", bg = "error_fill_on_canvas" }
marker_marked   = { fg = "warning_fill_on_canvas", bg = "warning_fill_on_canvas" }
marker_selected = { fg = "primary_fill_on_canvas", bg = "primary_fill_on_canvas" }
marker_symbol   = "│"

count_copied   = { fg = "on_success_fill_on_canvas", bg = "success_fill_on_canvas" }
count_cut      = { fg = "on_error_fill_on_canvas", bg = "error_fill_on_canvas" }
count_selected = { fg = "on_primary_fill_on_canvas", bg = "primary_fill_on_canvas" }

border_symbol = "│"
border_style  = { fg = "border_on_canvas" }
syntect_theme = ""

[indicator]
parent  = { fg = "muted_on_canvas" }
current = { fg = "on_primary_fill_on_canvas", bg = "primary_fill_on_canvas", bold = true }
preview = { fg = "info_text_on_canvas", underline = true }
padding = { open = "█", close = "█" }

[tabs]
active    = { fg = "on_primary_fill_on_canvas", bg = "primary_fill_on_canvas", bold = true, underline = true }
inactive  = { fg = "muted_on_panel", bg = "panel_bg", underline = true }
sep_inner = { open = "", close = "" }
sep_outer = { open = "", close = "" }

[mode]
normal_main = { fg = "on_primary_fill_on_canvas", bg = "primary_fill_on_canvas", bold = true }
normal_alt  = { fg = "primary_text_on_panel", bg = "panel_bg" }
select_main = { fg = "on_warning_fill_on_canvas", bg = "warning_fill_on_canvas", bold = true }
select_alt  = { fg = "warning_text_on_panel", bg = "panel_bg" }
unset_main  = { fg = "on_error_fill_on_canvas", bg = "error_fill_on_canvas", bold = true }
unset_alt   = { fg = "error_text_on_panel", bg = "panel_bg" }

[status]
overall   = { fg = "text_on_panel", bg = "panel_bg" }
sep_left  = { open = "", close = "" }
sep_right = { open = "", close = "" }

progress_label  = { fg = "text_on_panel", bold = true }
progress_normal = { fg = "primary_visible_on_surface", bg = "surface_fill" }
progress_error  = { fg = "error_visible_on_panel", bg = "panel_bg" }

perm_type  = { fg = "info_text_on_panel" }
perm_read  = { fg = "warning_text_on_panel" }
perm_write = { fg = "error_text_on_panel" }
perm_exec  = { fg = "success_text_on_panel" }
perm_sep   = { fg = "muted_on_panel" }

[pick]
border   = { fg = "border_on_canvas" }
active   = { fg = "primary_text_on_canvas", bold = true }
inactive = { fg = "text_on_canvas" }

[input]
border   = { fg = "border_on_canvas" }
title    = { fg = "primary_text_on_canvas", bold = true }
value    = { fg = "text_on_canvas" }
selected = { fg = "on_primary_fill_on_canvas", bg = "primary_fill_on_canvas" }

[tasks]
border  = { fg = "border_on_canvas" }
title   = { fg = "primary_text_on_canvas", bold = true }
hovered = { fg = "on_primary_fill_on_canvas", bg = "primary_fill_on_canvas" }

[which]
cols            = 3
mask            = { bg = "panel_bg" }
border          = { fg = "border_on_panel" }
cand            = { fg = "primary_text_on_panel", bold = true }
rest            = { fg = "disabled_on_panel" }
desc            = { fg = "text_on_panel" }
separator       = "  "
separator_style = { fg = "border_on_panel" }

[help]
border  = { fg = "border_on_canvas" }
chord   = { fg = "primary_text_on_canvas", bold = true }
action  = { fg = "text_on_canvas" }
hovered = { fg = "on_primary_fill_on_canvas", bg = "primary_fill_on_canvas", bold = true }

[notify]
title_info  = { fg = "info_text_on_canvas" }
title_warn  = { fg = "warning_text_on_canvas" }
title_error = { fg = "error_text_on_canvas" }
icon_info   = ""
icon_warn   = ""
icon_error  = ""

[confirm]
border     = { fg = "border_on_canvas" }
title      = { fg = "primary_text_on_canvas", bold = true }
body       = { fg = "text_on_canvas" }
list       = { fg = "text_on_canvas" }
btn_yes    = { fg = "on_primary_fill_on_canvas", bg = "primary_fill_on_canvas", bold = true }
btn_no     = { fg = "text_on_canvas" }
btn_labels = ["  [Y]es  ", "  (N)o  "]

[filetype]
rules = [
  { url = "*", is = "orphan", fg = "error_text_on_canvas" },
  { url = "*", is = "dummy", fg = "error_text_on_canvas" },
  { url = "*", is = "exec", fg = "success_text_on_canvas" },
  { mime = "**/image/*", fg = "ansi_magenta_text_on_canvas" },
  { mime = "**/{audio,video}/*", fg = "ansi_yellow_text_on_canvas" },
  { mime = "**/application/{zip,rar,7z*,tar,gzip,xz,zstd,bzip*,lzma,compress,archive,cpio,arj,xar,ms-cab*}", fg = "ansi_red_text_on_canvas" },
  { mime = "**/application/{pdf,doc,rtf}", fg = "ansi_cyan_text_on_canvas" },
  { mime = "vfs/{absent,stale}", fg = "muted_on_canvas" },
  { url = "*/", is = "dummy", fg = "error_text_on_canvas" },
  { url = "*/", fg = "info_text_on_canvas" },
  { url = "*", fg = "text_on_canvas" },
]

[spot]
border   = { fg = "border_on_canvas" }
title    = { fg = "primary_text_on_canvas", bold = true }
tbl_col  = { fg = "primary_text_on_canvas", bold = true }
tbl_cell = { fg = "text_on_canvas" }

[cmp]
border       = { fg = "border_on_canvas" }
active       = { fg = "on_primary_fill_on_canvas", bg = "primary_fill_on_canvas", bold = true }
inactive     = { fg = "text_on_canvas" }
icon_file    = ""
icon_folder  = ""
icon_command = ""

[icon]
prepend_conds = [{ if = "dir", text = "", fg = "info_text_on_canvas" }]
prepend_dirs = [
  { name = "Desktop", text = "", fg = "info_text_on_canvas" },
  { name = "Downloads", text = "", fg = "info_text_on_canvas" },
  { name = "Documents", text = "", fg = "info_text_on_canvas" },
  { name = "Music", text = "", fg = "info_text_on_canvas" },
  { name = "Pictures", text = "", fg = "info_text_on_canvas" },
  { name = "Videos", text = "", fg = "info_text_on_canvas" },
  { name = "Books", text = "", fg = "info_text_on_canvas" },
  { name = "dotfiles", text = "", fg = "info_text_on_canvas" },
  { name = "projects", text = "", fg = "info_text_on_canvas" },
]

sources.theme/maps/tmux.toml:
[colors]
bg = "canvas_bg"
fg = "text_on_canvas"
surface = "surface_fill"
surface_fg = "text_on_surface"
muted = "muted_on_canvas"
border = "border_on_canvas"
primary = "primary_text_on_canvas"
on_primary = "on(primary_text_on_canvas,4.5)"
active_bg = "primary_fill_on_canvas"
active_fg = "on_primary_fill_on_canvas"
selection_bg = "primary_fill_on_canvas"
selection_fg = "on_primary_fill_on_canvas"
success = "success_text_on_canvas"
warning = "warning_text_on_canvas"
error = "error_text_on_canvas"
match_bg = "warning_fill_on_canvas"
match_fg = "on_warning_fill_on_canvas"

[styles]
status-style = { fg = "fg", bg = "bg" }
message-style = { fg = "surface_fg", bg = "surface" }
message-command-style = { fg = "active_fg", bg = "active_bg", attrs = "bold" }
mode-style = { fg = "selection_fg", bg = "selection_bg", attrs = "bold" }
pane-border-style = { fg = "border", bg = "bg", floor = 3.0 }
pane-active-border-style = { fg = "primary", bg = "bg", floor = 3.0 }
popup-style = { fg = "fg", bg = "bg" }
popup-border-style = { fg = "primary", bg = "bg", floor = 3.0 }
menu-style = { fg = "fg", bg = "bg" }
menu-selected-style = { fg = "active_fg", bg = "active_bg", attrs = "bold" }
menu-border-style = { fg = "primary", bg = "bg", floor = 3.0 }
window-status-style = { fg = "muted", bg = "bg" }
window-status-current-style = { fg = "active_fg", bg = "active_bg", attrs = "bold" }
window-status-last-style = { fg = "fg", bg = "bg" }
window-status-activity-style = { fg = "success", bg = "bg" }
window-status-bell-style = { fg = "warning", bg = "bg", attrs = "bold" }
copy-mode-match-style = { fg = "match_fg", bg = "match_bg" }
copy-mode-current-match-style = { fg = "selection_fg", bg = "selection_bg", attrs = "bold" }
copy-mode-selection-style = { fg = "selection_fg", bg = "selection_bg" }
copy-mode-position-style = { fg = "active_fg", bg = "active_bg", attrs = "bold" }
copy-mode-mark-style = { fg = "surface_fg", bg = "surface" }
copy-mode-line-number-style = { fg = "muted", bg = "bg" }
copy-mode-current-line-number-style = { fg = "primary", bg = "bg", attrs = "bold" }

[fzf]
bg = "bg"
gutter = "bg"
fg = "fg"
"bg+" = "active_bg"
"fg+" = "active_fg"
hl = "primary"
"hl+" = "active_fg"
header = "muted"
info = "muted"
prompt = "primary"
pointer = "primary"
marker = "success"
spinner = "primary"
border = "border"
label = "primary"
"preview-bg" = "bg"
"preview-fg" = "fg"

