# Yazi theme contract: 26.8.15+

# Generated from theme/profiles/sexy-purple.toml

[app]
overall = { bg = "#15152b" }

[mgr]
cwd            = { fg = "#81a1c1" }
find_keyword   = { fg = "#15152b", bg = "#ebcb8b", italic = true }
find_position  = { fg = "#ebcb8b", bg = "reset", italic = true }
symlink_target = { fg = "#9798a4", italic = true }

# Equal foreground and background intentionally render a solid marker cell.
marker_copied   = { fg = "#a3be8c", bg = "#a3be8c" }
marker_cut      = { fg = "#bf616a", bg = "#bf616a" }
marker_marked   = { fg = "#ebcb8b", bg = "#ebcb8b" }
marker_selected = { fg = "#7252af", bg = "#7252af" }
marker_symbol   = "│"

count_copied   = { fg = "#15152b", bg = "#a3be8c" }
count_cut      = { fg = "#000000", bg = "#bf616a" }
count_selected = { fg = "#ffffff", bg = "#7252af" }

border_symbol = "│"
border_style  = { fg = "#616279" }
syntect_theme = ""

[indicator]
parent  = { fg = "#9798a4" }
current = { fg = "#ffffff", bg = "#7252af", bold = true }
preview = { fg = "#81a1c1", underline = true }
padding = { open = "█", close = "█" }

[tabs]
active    = { fg = "#ffffff", bg = "#7252af", bold = true, underline = true }
inactive  = { fg = "#95959e", bg = "#101020", underline = true }
sep_inner = { open = "", close = "" }
sep_outer = { open = "", close = "" }

[mode]
normal_main = { fg = "#ffffff", bg = "#7252af", bold = true }
normal_alt  = { fg = "#8b6bcb", bg = "#101020" }
select_main = { fg = "#15152b", bg = "#ebcb8b", bold = true }
select_alt  = { fg = "#ebcb8b", bg = "#101020" }
unset_main  = { fg = "#000000", bg = "#bf616a", bold = true }
unset_alt   = { fg = "#bf616a", bg = "#101020" }

[status]
overall   = { fg = "#ffffff", bg = "#101020" }
sep_left  = { open = "", close = "" }
sep_right = { open = "", close = "" }

progress_label  = { fg = "#ffffff", bold = true }
progress_normal = { fg = "#8b6bcb", bg = "#313247" }
progress_error  = { fg = "#bf616a", bg = "#101020" }

perm_type  = { fg = "#81a1c1" }
perm_read  = { fg = "#ebcb8b" }
perm_write = { fg = "#bf616a" }
perm_exec  = { fg = "#a3be8c" }
perm_sep   = { fg = "#95959e" }

[pick]
border   = { fg = "#616279" }
active   = { fg = "#8e6fcf", bold = true }
inactive = { fg = "#ffffff" }

[input]
border   = { fg = "#616279" }
title    = { fg = "#8e6fcf", bold = true }
value    = { fg = "#ffffff" }
selected = { fg = "#ffffff", bg = "#7252af" }

[tasks]
border  = { fg = "#616279" }
title   = { fg = "#8e6fcf", bold = true }
hovered = { fg = "#ffffff", bg = "#7252af" }

[which]
cols            = 3
mask            = { bg = "#101020" }
border          = { fg = "#5d5f76" }
cand            = { fg = "#8b6bcb", bold = true }
rest            = { fg = "#70717c" }
desc            = { fg = "#ffffff" }
separator       = "  "
separator_style = { fg = "#5d5f76" }

[help]
border  = { fg = "#616279" }
chord   = { fg = "#8e6fcf", bold = true }
action  = { fg = "#ffffff" }
hovered = { fg = "#ffffff", bg = "#7252af", bold = true }

[notify]
title_info  = { fg = "#81a1c1" }
title_warn  = { fg = "#ebcb8b" }
title_error = { fg = "#c2636c" }
icon_info   = ""
icon_warn   = ""
icon_error  = ""

[confirm]
border     = { fg = "#616279" }
title      = { fg = "#8e6fcf", bold = true }
body       = { fg = "#ffffff" }
list       = { fg = "#ffffff" }
btn_yes    = { fg = "#ffffff", bg = "#7252af", bold = true }
btn_no     = { fg = "#ffffff" }
btn_labels = ["  [Y]es  ", "  (N)o  "]

[filetype]
rules = [
  { url = "*", is = "orphan", fg = "#c2636c" },
  { url = "*", is = "dummy", fg = "#c2636c" },
  { url = "*", is = "exec", fg = "#a3be8c" },
  { mime = "**/image/*", fg = "#b48ead" },
  { mime = "**/{audio,video}/*", fg = "#ebcb8b" },
  { mime = "**/application/{zip,rar,7z*,tar,gzip,xz,zstd,bzip*,lzma,compress,archive,cpio,arj,xar,ms-cab*}", fg = "#c2636c" },
  { mime = "**/application/{pdf,doc,rtf}", fg = "#88c0d0" },
  { mime = "vfs/{absent,stale}", fg = "#9798a4" },
  { url = "*/", is = "dummy", fg = "#c2636c" },
  { url = "*/", fg = "#81a1c1" },
  { url = "*", fg = "#ffffff" },
]

[spot]
