body {
  --file-line-width: 780px;
  --file-folding-offset: 24px;
  --input-radius: var(--radius-m);
  --button-radius: var(--radius-m);
  --tab-radius-active: var(--radius-m) var(--radius-m) 0 0;
  --nav-item-radius: var(--radius-s);
}

::selection {
  background: var(--selection-background);
  color: var(--text-normal);
}

.workspace,
.workspace-split.mod-root .view-content {
  background: var(--background-primary);
}

.workspace-tab-header-container {
  border-bottom: 1px solid var(--background-modifier-border);
}

.workspace-tab-header.is-active {
  box-shadow: inset 0 -2px var(--interactive-accent);
}

.workspace-tab-header.is-active::before,
.workspace-tab-header.is-active::after {
  display: none;
}

.nav-file-title,
.nav-folder-title,
.menu-item,
.suggestion-item {
  transition:
    background-color 120ms ease,
    color 120ms ease;
}

.nav-file-title.is-active,
.nav-folder-title.is-active {
  font-weight: 600;
}

.markdown-rendered h1,
.markdown-rendered h2,
.markdown-rendered h3,
.markdown-rendered h4,
.markdown-rendered h5,
.markdown-rendered h6,
.markdown-source-view.mod-cm6 .cm-header {
  letter-spacing: -0.015em;
}

.markdown-rendered h1 {
  border-bottom: 1px solid var(--background-modifier-border);
  padding-bottom: 0.35em;
}

.markdown-rendered blockquote {
  background: var(--background-secondary);
  border-radius: 0 var(--radius-m) var(--radius-m) 0;
  margin-inline: 0;
  padding: 0.5em 1em;
}

.markdown-rendered code,
.cm-s-obsidian span.cm-inline-code {
  border: 1px solid var(--background-modifier-border);
  border-radius: 5px;
  padding: 0.1em 0.35em;
}

.markdown-rendered pre {
  border: 1px solid var(--background-modifier-border);
  border-radius: var(--radius-m);
  box-shadow: 0 8px 24px var(--code-block-shadow);
}

.markdown-rendered pre code {
  border: 0;
  padding: 0;
}

.markdown-rendered table {
  border-collapse: separate;
  border-spacing: 0;
  overflow: hidden;
}

.markdown-rendered th:first-child {
  border-top-left-radius: var(--radius-s);
}

.markdown-rendered th:last-child {
  border-top-right-radius: var(--radius-s);
}

.callout {
  background: rgba(var(--callout-color), 0.1);
  border: 1px solid rgba(var(--callout-color), 0.3);
  border-radius: var(--radius-m);
}

.callout-title {
  font-weight: 650;
}

.callout[data-callout="note"],
.callout[data-callout="info"],
.callout[data-callout="todo"] {
  --callout-color: var(--color-blue-rgb);
}

.callout[data-callout="abstract"],
.callout[data-callout="summary"],
.callout[data-callout="tldr"],
.callout[data-callout="tip"],
.callout[data-callout="hint"],
.callout[data-callout="important"] {
  --callout-color: var(--color-cyan-rgb);
}

.callout[data-callout="success"],
.callout[data-callout="check"],
.callout[data-callout="done"] {
  --callout-color: var(--color-green-rgb);
}

.callout[data-callout="question"],
.callout[data-callout="help"],
.callout[data-callout="faq"],
.callout[data-callout="warning"],
.callout[data-callout="caution"],
.callout[data-callout="attention"] {
  --callout-color: var(--color-yellow-rgb);
}

.callout[data-callout="failure"],
.callout[data-callout="fail"],
