chord   = { fg = "#8e6fcf", bold = true }
action  = { fg = "#ffffff" }
hovered = { fg = "#ffffff", bg = "#7252af", bold = true }

[notify]
title_info  = { fg = "#81a1c1" }
title_warn  = { fg = "#ebcb8b" }
title_error = { fg = "#c2636c" }
icon_info   = ""
icon_warn   = ""
icon_error  = ""

[confirm]
border     = { fg = "#616279" }
title      = { fg = "#8e6fcf", bold = true }
body       = { fg = "#ffffff" }
list       = { fg = "#ffffff" }
btn_yes    = { fg = "#ffffff", bg = "#7252af", bold = true }
btn_no     = { fg = "#ffffff" }
btn_labels = ["  [Y]es  ", "  (N)o  "]

[filetype]
rules = [
  { url = "*", is = "orphan", fg = "#c2636c" },
  { url = "*", is = "dummy", fg = "#c2636c" },
  { url = "*", is = "exec", fg = "#a3be8c" },
  { mime = "**/image/*", fg = "#b48ead" },
  { mime = "**/{audio,video}/*", fg = "#ebcb8b" },
  { mime = "**/application/{zip,rar,7z*,tar,gzip,xz,zstd,bzip*,lzma,compress,archive,cpio,arj,xar,ms-cab*}", fg = "#c2636c" },
  { mime = "**/application/{pdf,doc,rtf}", fg = "#88c0d0" },
  { mime = "vfs/{absent,stale}", fg = "#9798a4" },
  { url = "*/", is = "dummy", fg = "#c2636c" },
  { url = "*/", fg = "#81a1c1" },
  { url = "*", fg = "#ffffff" },
]

[spot]
border   = { fg = "#616279" }
title    = { fg = "#8e6fcf", bold = true }
tbl_col  = { fg = "#8e6fcf", bold = true }
tbl_cell = { fg = "#ffffff" }

[cmp]
border       = { fg = "#616279" }
active       = { fg = "#ffffff", bg = "#7252af", bold = true }
inactive     = { fg = "#ffffff" }
icon_file    = ""
icon_folder  = ""
icon_command = ""

[icon]
prepend_conds = [{ if = "dir", text = "", fg = "#81a1c1" }]
prepend_dirs = [
  { name = "Desktop", text = "", fg = "#81a1c1" },
  { name = "Downloads", text = "", fg = "#81a1c1" },
  { name = "Documents", text = "", fg = "#81a1c1" },
  { name = "Music", text = "", fg = "#81a1c1" },
  { name = "Pictures", text = "", fg = "#81a1c1" },
  { name = "Videos", text = "", fg = "#81a1c1" },
  { name = "Books", text = "", fg = "#81a1c1" },
  { name = "dotfiles", text = "", fg = "#81a1c1" },
  { name = "projects", text = "", fg = "#81a1c1" },
]

